     1	#!/usr/bin/env node
     2	/**
     3	 * Populate .env with Contentful API tokens fetched live from the space.
     4	 *
     5	 * Rules:
     6	 *   - Missing var  → added at the end of the Contentful block
     7	 *   - Empty var    → filled with the live value
     8	 *   - Wrong var    → updated with the live value
     9	 *   - CONTENTFUL_MANAGEMENT_TOKEN → never touched (per-user personal token)
    10	 *
    11	 * Write access (add/update) is gated to @ZimmermannAU/tier-1-approvers.
    12	 * Non-approvers get a read-only view of what the values should be.
    13	 *
    14	 * Usage:
    15	 *   npm run config:contentful               # update .env if authorised
    16	 *   npm run config:contentful -- --dry-run  # print changes without writing
    17	 */
